import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-text-moderation/plan.md","filePath":"feature/caption-text-moderation/plan.md"}'),i={name:"feature/caption-text-moderation/plan.md"};function s(n,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h1><ol><li>Add AI moderation models and service using DEPLOY_ACCESS_KEY, bounded requests with total budget and no automatic retry; normalize documented V3 responses and aggregate segment verdicts conservatively.</li><li>Add authenticated internal moderation endpoint and attach verdict to generic generated captions. Add optional compliance to structured caption models and check generate/refine/adapt outputs at route boundary.</li><li>Map returned compliance in business caption adapter, replacing the NOT_CHECKED stub with a parser. Add workspace manual check using existing role and access checks. No schema/credit changes.</li><li>Add typed moderation service, shared result/check component and hook. Wire editor generated results and Content Writing draft. An edited generated caption needs a new check before Apply.</li><li>Update brandhub-web/src/i18n/locales/{vi,en}/editor.json. Use existing border/card/destructive tokens; verify light/dark, responsive and keyboard.</li><li>Unit-test provider parsing, segmentation, timeouts/auth failures and HTTP endpoint authentication using mocks. Run Java adapter tests and web typecheck/build.</li></ol><p>Sources: <a href="https://docs.deploy.com/quickstart" target="_blank" rel="noreferrer">https://docs.deploy.com/quickstart</a> and <a href="https://docs.thehive.ai/docs/text-moderation-api" target="_blank" rel="noreferrer">https://docs.thehive.ai/docs/text-moderation-api</a>. Playground contract source: <a href="https://docs.thehive.ai/docs/text-moderation-playground" target="_blank" rel="noreferrer">https://docs.thehive.ai/docs/text-moderation-playground</a>. Verify exact key compatibility using the approved V3 endpoint.</p><ol start="7"><li><p>Add a small editor moderation coordinator with a 3-second timer, cancellation, exact snapshot caching and in-flight deduplication; a React hook subscribes to it.</p></li><li><p>EditorWorkspace wires caption/hashtags into that hook, displays inline status and gates onPublishNow before invoking the form handler; guards duplicate clicks throughout check+publish. Do not change API keys or existing backend publishing flow.</p></li><li><p>Add fake-timer/request-race unit tests and Playwright request-order tests, update vi/en editor locales.</p></li><li><p>Classify moderation failures at the provider boundary; preserve aggregation and dedicated-key behavior. Add parallel vi/en issue labels through existing components. Use mocked failure tests and log-redaction assertions; no live credential transmission.</p></li><li><p>Normalize known entity/PII filter types, validate filter containers, retain blocking IWF and unknown custom matches. Add unsupported_&lt;category&gt; issue codes and fixed category-only logs. Update vi/en status/recovery text in existing components without theme/layout changes. Verify provider and editor coordinator regressions offline. Source: <a href="https://docs.thehive.ai/docs/classification-text" target="_blank" rel="noreferrer">https://docs.thehive.ai/docs/classification-text</a> (language coverage, -1 semantics, filter types).</p></li></ol><h2 id="generic-partial-response-diagnosis" tabindex="-1">Generic partial response diagnosis <a class="header-anchor" href="#generic-partial-response-diagnosis" aria-label="Permalink to &quot;Generic partial response diagnosis&quot;">​</a></h2><p>At normalization boundaries log only fixed reason codes and field types/counts, not provider data or text. Log unrecognized-class count and classification coverage.</p><h2 id="class-entry-contract-correction" tabindex="-1">Class entry contract correction <a class="header-anchor" href="#class-entry-contract-correction" aria-label="Permalink to &quot;Class entry contract correction&quot;">​</a></h2><p>Parse whole field pairs, prefer documented class/score when present; accept both pairs only if name and typed severity agree. Regression through moderate_text HTTP response boundary. Source <a href="https://docs.thehive.ai/docs/text-moderation-api" target="_blank" rel="noreferrer">https://docs.thehive.ai/docs/text-moderation-api</a> .</p><h2 id="live-schema-diagnosis" tabindex="-1">Live schema diagnosis <a class="header-anchor" href="#live-schema-diagnosis" aria-label="Permalink to &quot;Live schema diagnosis&quot;">​</a></h2><p>Log the first class entry shape once per provider output with field types for class, class_name, name, score, value, severity, category. Correct parsing only after observing live schema.</p><h2 id="observed-v3-class-value-schema" tabindex="-1">Observed V3 class/value schema <a class="header-anchor" href="#observed-v3-class-value-schema" aria-label="Permalink to &quot;Observed V3 class/value schema&quot;">​</a></h2><p>Use explicit class/value, class/score, class_name/value pairs. Validate redundant aliases before normalization. Replace default fixture with observed live class/value shape. Remove temporary schema instrumentation.</p><h2 id="partial-coverage-policy-reloop-reference" tabindex="-1">Partial coverage policy (ReLoop reference) <a class="header-anchor" href="#partial-coverage-policy-reloop-reference" aria-label="Permalink to &quot;Partial coverage policy (ReLoop reference)&quot;">​</a></h2><p>Separate explicit per-category -1 from incomplete/error flags. Supported benign classifications plus -1 =&gt; WARNING. Keep all-unsupported/error aggregation conservative. Add coveragePartial vi/en copy in both moderation components. Keep existing semantic theme/layout, debounce 3s and gate. Validate provider and editor gate regression.</p><h2 id="user-requested-unsupported-as-safe-policy" tabindex="-1">User requested unsupported-as-safe policy <a class="header-anchor" href="#user-requested-unsupported-as-safe-policy" aria-label="Permalink to &quot;User requested unsupported-as-safe policy&quot;">​</a></h2><p>Remove unsupported issues; count valid -1 classifications as evaluated for user policy. Add nullable score across Python, Java and TypeScript; render severity beside actual issues. Log detection JSON with bounded matched excerpt and nullable score.</p>',16)])])}const g=a(i,[["render",s]]);export{h as __pageData,g as default};
